import boto3
import os


def get_s3_client(region_name=None):
    region = region_name or os.environ.get("AWS_REGION")
    if not region:
        raise ValueError("AWS region not specified and not found in environment variables.")
    return boto3.client("s3", region_name=region)

from typing import Dict, Any, Optional


def UploadObjectPayload(object_name: str, data: Any, content_type: Optional[str] = None) -> Dict[str, Any]:
    payload = {"object_name": object_name, "data": data}
    if content_type:
        payload["content_type"] = content_type
    return payload


def UploadObjectResponse(object_name: str) -> Dict[str, str]:
    return {"object_name": object_name}


def PresignedDownloadPayload(object_name: str, expiration_seconds: int = 3600) -> Dict[str, Any]:
    return {"object_name": object_name, "expiration_seconds": expiration_seconds}


def PresignedDownloadResponse(object_name: str, url: str) -> Dict[str, str]:
    return {"object_name": object_name, "url": url}


def ObjectMetadataPayload(object_name: str) -> Dict[str, str]:
    return {"object_name": object_name}


def ObjectMetadataResponse(object_name: str, metadata: Dict[str, Any]) -> Dict[str, Any]:
    return {"object_name": object_name, "metadata": metadata}


def ListPrefixPayload(prefix: str, max_keys: int = 100) -> Dict[str, Any]:
    return {"prefix": prefix, "max_keys": max_keys}


def ListPrefixResponse(prefix: str, objects: list) -> Dict[str, Any]:
    return {"prefix": prefix, "objects": objects}

from storage_client import get_s3_client
from storage_models import PresignedDownloadPayload, PresignedDownloadResponse


def presigned_download(payload, config=None):
    config = config or {}
    client = get_s3_client(region_name=config.get("region"))
    object_name = payload["object_name"]
    expiration_seconds = payload.get("expiration_seconds", 3600)

    url = client.generate_presigned_url(
        'get_object',
        Params={'Bucket': config["bucket"], 'Key': object_name},
        ExpiresIn=expiration_seconds
    )
    return PresignedDownloadResponse(object_name=object_name, url=url)

from storage_client import get_s3_client
from storage_models import ObjectMetadataPayload, ObjectMetadataResponse


def object_metadata(payload, config=None):
    config = config or {}
    client = get_s3_client(region_name=config.get("region"))
    object_name = payload["object_name"]

    response = client.head_object(Bucket=config["bucket"], Key=object_name)
    metadata = {
        "content_type": response.get("ContentType"),
        "last_modified": response.get("LastModified").isoformat() if response.get("LastModified") else None,
        "content_length": response.get("ContentLength"),
        **response.get("Metadata", {})
    }
    return ObjectMetadataResponse(object_name=object_name, metadata=metadata)

from storage_client import get_s3_client
from storage_models import ListPrefixPayload, ListPrefixResponse


def list_prefix(payload, config=None):
    config = config or {}
    client = get_s3_client(region_name=config.get("region"))
    prefix = payload["prefix"]
    max_keys = payload.get("max_keys", 100)

    response = client.list_objects_v2(Bucket=config["bucket"], Prefix=prefix, MaxKeys=max_keys)
    objects = []
    for obj in response.get("Contents", []):
        objects.append({"key": obj["Key"], "size": obj["Size"], "last_modified": obj["LastModified"].isoformat()})

    return ListPrefixResponse(prefix=prefix, objects=objects)

import boto3
import os


def stored_document_ocr(payload, config=None):
    config = config or {}
    textract_client = boto3.client("textract", region_name=config.get("region") or os.environ.get("AWS_REGION"))
    s3_object_name = payload["object_name"]

    response = textract_client.detect_document_text(
        Document={
            'S3Object': {
                'Bucket': config["bucket"],
                'Name': s3_object_name
            }
        }
    )

    extracted_text = []
    for item in response["Blocks"]:
        if item["BlockType"] == "LINE":
            extracted_text.append(item["Text"])

    return {"object_name": s3_object_name, "extracted_text": "\n".join(extracted_text)}

import boto3
import os


def stored_text_translate(payload, config=None):
    config = config or {}
    translate_client = boto3.client("translate", region_name=config.get("region") or os.environ.get("AWS_REGION"))
    text_to_translate = payload["text"]
    target_language_code = payload.get("target_language", "en")  # Default to English
    source_language_code = payload.get("source_language", "auto") # Default to auto-detect

    if source_language_code == "auto":
        response = translate_client.translate_text(
            Text=text_to_translate,
            SourceLanguageCode="auto",
            TargetLanguageCode=target_language_code
        )
    else:
        response = translate_client.translate_text(
            Text=text_to_translate,
            SourceLanguageCode=source_language_code,
            TargetLanguageCode=target_language_code
        )

    translated_text = response["TranslatedText"]
    return {"original_text": text_to_translate, "translated_text": translated_text, "target_language": target_language_code}
